-- =============================================================================
-- Seed de DEMONSTRAÇÃO — dados fictícios para validar telas, fluxos e RLS.
--
-- Aplicado depois do seed_prod.sql. Nomes, CPFs, endereços e valores são
-- inventados; o bloco de saúde traz só rótulos genéricos. Datas são relativas
-- ao momento da carga, para os painéis sempre terem histórico recente.
--
-- Variável psql obrigatória: demo_password (senha de todas as contas demo).
--
-- Contas de teste (uma por papel):
--   super_admin  helena@alcanceisencoes.com.br
--   gestor       bruno@alcanceisencoes.com.br
--   analista     tatiane@alcanceisencoes.com.br
--   cliente      carlos.ferraz2@exemplo.com.br
--   (inativa)    sofia@alcanceisencoes.com.br — login deve ser recusado
--
-- Gerado a partir da antiga base simulada do front-end.
-- =============================================================================

\set ON_ERROR_STOP on

select set_config('app.seeding', 'on', false);
select set_config('seed.demo_password', :'demo_password', false);

do $$
begin
  if length(current_setting('seed.demo_password')) < 8 then
    raise exception 'DEMO_PASSWORD deve ter ao menos 8 caracteres.';
  end if;
end
$$;

create function pg_temp.create_login(p_id uuid, p_email text, p_name text, p_banned boolean)
returns void
language sql
as $$
  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, banned_until, created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change
  ) values (
    '00000000-0000-0000-0000-000000000000', p_id, 'authenticated', 'authenticated', p_email,
    extensions.crypt(current_setting('seed.demo_password'), extensions.gen_salt('bf')), now(),
    '{"provider": "email", "providers": ["email"]}'::jsonb,
    jsonb_build_object('full_name', p_name),
    case when p_banned then timestamptz '2126-01-01 00:00:00+00' end,
    now(), now(), '', '', '', ''
  );
  insert into auth.identities (id, user_id, provider_id, identity_data, provider, created_at, updated_at)
  values (gen_random_uuid(), p_id, p_id::text,
          jsonb_build_object('sub', p_id::text, 'email', p_email, 'email_verified', true),
          'email', now(), now());
$$;

